import json,sys,re,subprocess
from pathlib import Path
from datetime import datetime,timezone
extra=json.loads(sys.argv[1])
reviewer="/root/rv1019_reader_ch01b"
base=Path("docs/course-review-20261019/reviews/rv1019_reader_ch01b")
paths=[base/"reader-recheck-01.json",base/"reader-current-02.json",base/"reader-closure-02.json"]
for path in paths:
    if path.exists():
        raise SystemExit("Destination already exists; refusing to overwrite: "+str(path))
def sha(path):
    output=subprocess.run(["shasum","-a","256",str(path)],check=True,capture_output=True,text=True).stdout
    return output.split()[0]
def now():
    return datetime.now(timezone.utc).isoformat()
def part(text):
    match=re.search(r"判定[：:]\s*(已足夠|需補說明|合理待教|未驗證)",text)
    assert match
    return {"answer":text[:match.start()].strip(),"verdict":match.group(1)}
def write_once(path,value):
    with path.open("x",encoding="utf-8") as file:
        file.write(json.dumps(value,ensure_ascii=False,indent=2)+"\n")
    assert json.loads(path.read_text())==value
    return sha(path)
original_path=base/"reader-original-01.json"
original_hash=sha(original_path)
assert original_hash=="c27cde01b750f11561cc37d594eb83fd459a6ba5758eeb8b2301b2054765cac1"
original=json.loads(original_path.read_text())
old_page=next(p for p in original["pages"] if p["page_id"]=="1.4")
old_session="08da1e57a25448dfa56a4a794694ce76"
new_session="1105bec51ed246719a062a51a4efb02e"
root=Path("docs/course-revision-20261016/reader-sessions")
collected={}
pending={}
before_hashes={}
for session in (old_session,new_session):
    folder=root/session
    opening_path=folder/"opening.json"
    opening=json.loads(opening_path.read_text())
    assert opening["page_id"]=="1.4" and opening["reviewer_task"]==reviewer
    note_paths=sorted(folder.glob("note-*.json"))
    notes=[]
    for index,path in enumerate(note_paths):
        data=json.loads(path.read_text())
        assert data["unit_index"]==index and data["reviewer_task"]==reviewer
        digest=sha(path)
        before_hashes[str(path)]=digest
        notes.append({"path":path,"sha256":digest,"data":data})
        for concept_index,c in enumerate(data["concept_checks"]):
            if c["verdict"]!="已足夠":
                key=(session,path.name,concept_index)
                assert key not in pending
                pending[key]={"note":{"path":str(path),"sha256":digest},"original_verdict":c["verdict"]}
    assert len(notes)==3
    state=json.loads((folder/"state.json").read_text())
    assert state["next_index"]==len(notes)
    collected[session]={"opening_path":opening_path,"opening":opening,"notes":notes}
assert set(pending)=={(old_session,"note-001.json",0)}
old_notes=collected[old_session]["notes"]
new=collected[new_session]
assert all(a["data"]["unit_sha256"]==b["data"]["unit_sha256"] for a,b in zip(old_notes,new["notes"],strict=True))
opening=new["opening"]
freeze_path="docs/course-review-20261019/freeze-02.json"
plan_path="docs/course-review-20261019/reader-plan-ch01-recheck-01.json"
freeze={"path":freeze_path,"sha256":sha(freeze_path)}
plan={"path":plan_path,"sha256":sha(plan_path)}
assert opening["source_freeze"]==freeze and opening["reading_plan"]==plan
checks=[]
for note in new["notes"]:
    for c in note["data"]["concept_checks"]:
        checks.append({
            "concept":c["concept"],"identity":c["identity"],
            "mechanism":part(c["mechanism"]),"need":part(c["need"]),
            "usage":c["usage"],"example_scope":c["example_scope"],
            "source_quote":c["source_quote"],"verdict":c["verdict"]
        })
checks.append(extra["optional_check"])
assert all(c["verdict"]=="已足夠" for c in checks)
assert opening["figures_sha256"]=={}
page={
    "page_id":"1.4",
    "source_sha256":opening["source_sha256"],
    "figures_sha256":opening["figures_sha256"],
    "verdict":"pass",
    "reader_summary":"不輸入前文時，用單字次數除總數建立unigram分配，供後續比較的基準。能讀Counter程式及CPU輸出，分清次數與佔比、分配與選字，並說明相同分配無法利用前後字關係。修改後選讀把Counter可沿用的字典介面具體限定為本節的values和items，主要概念與操作仍可完整理解。",
    "checks":checks,
    "issues":[],
    "unknowns":["Counter未在本節使用的其他介面行為不在此次重讀範圍；本頁所需的values、items與計數操作已交代，不需先掌握所有介面。"],
    "missing_visuals":"無。五份字袋、次數和機率字典、改成七份後的比例都完整列出，可直接追蹤。沒有凍結圖；本次未驗證網站桌機/手機版面。",
    "figures_viewed":[],
    "optional_reading_observation":"本次在三個正文單元及CPU輸出讀完後才補讀選讀。選讀現在寫『所以本節用到的 .values()、.items() 都能照用』，將工具說明限於實際程式使用的兩個方法；仍補充未出現字取值為0、不引發KeyError，以及uni為一、bigram為相鄰兩字。這項收窄避免把局部使用外推到所有字典操作，不改變本頁計數與比例的主要理解。本次未執行缺字查詢或教材練習。",
    "ai_estimate":old_page["ai_estimate"],
    "session":new_session,
    "session_evidence":{
        "opening":{"path":str(new["opening_path"]),"sha256":sha(new["opening_path"])},
        "notes":[{"path":str(n["path"]),"sha256":n["sha256"]} for n in new["notes"]]
    }
}
recheck={
    "schema_version":1,"reviewer_task":reviewer,"created_at":now(),
    "report_kind":"recheck judgments after sequential rereading",
    "source_freeze":freeze,"reading_plan":plan,
    "context_reading":"這是既有首次閱讀者的重讀，使用先前實際讀過的暖身與教材知識，不宣稱新的盲讀。本次只用指定reader新計畫逐單元讀1.4，單元有程式後透過executed_outputs.py看此次CPU輸出，每次保存checkpoint才取下一單元，正文完成後才補讀1.4選讀。為核對變更與收束，只讀自身輸出目錄中的原報告之1.4條目及1.4兩個session的自身紀錄，沒有重讀其他頁、實作或外部資料，也沒有直接讀輸出清單。兩個session三個正文單元的unit_sha256逐項相同，頁面整體source_sha256不同；本次選讀將Counter的介面說明收窄為values/items。先前對Counter、abs和1e-6已學過，本次據實保留這項先備，而非再假裝未知。",
    "method_incidents":[],
    "pages":[page]
}
for c in checks:
    assert c["mechanism"]["verdict"]=="已足夠" and c["need"]["verdict"]=="已足夠"
    for key in ("concept","identity","usage","example_scope","source_quote"):
        assert c[key].strip()
assert page["ai_estimate"]["minutes_min"]>0
assert page["ai_estimate"]["minutes_max"]>=page["ai_estimate"]["minutes_min"]
recheck_hash=write_once(paths[0],recheck)
current={
    "schema_version":1,"reviewer_task":reviewer,"created_at":now(),
    "report_kind":"current judgments","source_freeze":freeze,"reading_plan":plan,
    "pages":[{
        "page_id":"1.4","source_sha256":page["source_sha256"],"figures_sha256":page["figures_sha256"],
        "verdict":page["verdict"],
        "basis_report":{"path":str(paths[0]),"sha256":recheck_hash},
        "ai_estimate":page["ai_estimate"]
    }]
}
assert datetime.fromisoformat(current["created_at"])>datetime.fromisoformat(recheck["created_at"])
current_hash=write_once(paths[1],current)
resolutions=[]
for key,entry in pending.items():
    resolutions.append({
        "note":entry["note"],"concept_index":key[2],"original_verdict":entry["original_verdict"],
        **extra["resolution"]
    })
closure={
    "schema_version":1,"reviewer_task":reviewer,"created_at":now(),
    "report_kind":"checkpoint closure",
    "basis_report":{"path":str(paths[1]),"sha256":current_hash},
    "pages":[{
        "page_id":"1.4","source_sha256":page["source_sha256"],"figures_sha256":page["figures_sha256"],
        "verdict":page["verdict"],"checkpoint_resolutions":resolutions
    }]
}
assert datetime.fromisoformat(closure["created_at"])>datetime.fromisoformat(current["created_at"])
assert len(resolutions)==len(pending)==1
assert resolutions[0]["final_status"]=="resolved"
closure_hash=write_once(paths[2],closure)
assert sha(original_path)==original_hash
assert all(sha(path)==digest for path,digest in before_hashes.items())
assert current["pages"][0]["ai_estimate"]==old_page["ai_estimate"]
assert len({(r["note"]["path"],r["concept_index"]) for r in resolutions})==len(pending)
print(json.dumps({
    "reviewer_task":reviewer,
    "files":[{"path":str(path),"sha256":digest} for path,digest in zip(paths,[recheck_hash,current_hash,closure_hash],strict=True)],
    "validation":{
        "recheck_pages":1,"current_pages":1,"closure_pages":1,"new_notes":len(new["notes"]),
        "old_non_sufficient":1,"new_non_sufficient":0,"checkpoint_resolutions":len(resolutions),
        "coverage_exact":True,"timestamps_ordered":True,"prior_records_unchanged":True,
        "verdict":"pass","ai_estimate_changed":False,"body_unit_hashes_unchanged":True
    }
},ensure_ascii=False,indent=2))

